bool test_batch_operations() {
    try {
        // Step 1: Create observer nodes
        auto var1 = reaction::var(10);
        auto var2 = reaction::var(20);
        auto calc1 = reaction::calc([&]() { return var1() + var2(); });
        auto calc2 = reaction::calc([&]() { return calc1() * 2; });

        // Step 2: Get observer graph instance
        auto& graph = reaction::ObserverGraph::getInstance();

        // Step 3: Create batch ID and register nodes to batch
        // The batch automatically collects observer nodes during construction
        auto batch = reaction::batch([&]() {
            var1.value(100);
            var2.value(200);
        });

        // Step 4 & 5: Verify nodes are in batch
        // We need to get the node pointers from the reactive wrappers
        // Since getPtr() is private, we'll use a workaround by creating NodePtrs
        // through the graph's name lookup or by using shared_from_this

        // Alternative approach: Test batch protection by trying to reset
        // If nodes are in batch, reset should throw an exception
        bool resetBlocked = false;
        try {
            calc1.reset([&]() { return var1() + 100; });
        } catch (const std::runtime_error&) {
            resetBlocked = true; // Expected: reset is blocked during active batch
        }

        if (!resetBlocked) {
            return false; // Batch protection should have prevented reset
        }

        // Step 6: Unregister batch (close it)
        batch.close();

        // Step 7: Verify nodes are no longer in batch
        // After closing, reset should work without throwing
        bool resetSucceeded = false;
        try {
            calc1.reset([&]() { return var1() + 100; });
            resetSucceeded = true;
        } catch (const std::runtime_error&) {
            resetSucceeded = false; // Should not throw after batch is closed
        }

        if (!resetSucceeded) {
            return false; // Reset should succeed after batch is closed
        }

        // Verify batch is closed
        if (!batch.isClosed()) {
            return false; // Batch should report as closed
        }

        // Step 8: Return success status
        return true;

    } catch (const std::exception&) {
        // If any unexpected exception occurs, test fails
        return false;
    }
}

