#pragma once

#include <reaction/reaction.h>

namespace test {

// ============================================
// 函数实现
// ============================================

/**
 * Function: Test batch operations on observer nodes
 *
 * @return bool Whether batch operations work correctly
 */
bool test_batch_operations() {
    try {
        // Step 1: Create observer nodes
        auto var1 = reaction::var(10);
        auto var2 = reaction::var(20);
        auto calc1 = reaction::calc([&]() { return var1() + var2(); });
        auto calc2 = reaction::calc([&]() { return calc1() * 2; });

        // Step 2: Get observer graph instance
        auto& graph = reaction::ObserverGraph::getInstance();

        // Step 3: Create batch ID (using the batch object as unique ID)
        auto batch = reaction::batch([&]() {
            var1.value(100);
            var2.value(200);
        });

        // Step 4: Register nodes to batch (already done automatically by batch constructor)
        // The batch constructor calls graph.registerActiveBatch() internally

        // Step 5: Verify nodes are in batch
        // Check if calc1 and calc2 nodes are in an active batch
        auto calc1Node = calc1.getNodePtr();
        auto calc2Node = calc2.getNodePtr();

        bool isCalc1InBatch = graph.isNodeInActiveBatch(calc1Node);
        bool isCalc2InBatch = graph.isNodeInActiveBatch(calc2Node);

        if (!isCalc1InBatch || !isCalc2InBatch) {
            return false; // Nodes should be in batch
        }

        // Step 6: Unregister batch
        batch.close();

        // Step 7: Verify nodes are no longer in batch
        isCalc1InBatch = graph.isNodeInActiveBatch(calc1Node);
        isCalc2InBatch = graph.isNodeInActiveBatch(calc2Node);

        if (isCalc1InBatch || isCalc2InBatch) {
            return false; // Nodes should no longer be in batch
        }

        // Step 8: Return success status
        return true;

    } catch (const std::exception& e) {
        // If any exception occurs, test fails
        return false;
    }
}

}  // namespace test
