class TestObserverClosure : public reaction::ObserverNode {
public:
    TestObserverClosure(const std::string& name) : m_name(name), m_changed(false) {}

    void valueChanged(bool changed = true) override {
        m_changed = changed;
        m_callCount++;
        // Call base class to propagate notification to observers
        ObserverNode::valueChanged(changed);
    }

    bool wasChanged() const { return m_changed; }
    int getCallCount() const { return m_callCount; }
    const std::string& getName() const { return m_name; }

private:
    std::string m_name;
    bool m_changed;
    int m_callCount = 0;
};

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test node closure functionality
 *
 * @param nodeName Name for the observer node
 * @return bool Whether node closure worked correctly (relationships cleaned up)
 */
bool test_node_closure(const std::string& nodeName) {
    // 1. Create observer nodes
    auto target = std::make_shared<TestObserverClosure>("target");
    auto observer = std::make_shared<TestObserverClosure>(nodeName);

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Add observer relationship (observer watches target)
    graph.addObserver(observer, target);

    // 4. Notify target and verify observer was notified
    target->valueChanged(true);
    if (!observer->wasChanged() || observer->getCallCount() != 1) {
        return false;
    }

    // 5. Reset observer state
    observer->valueChanged(false);

    // 6. Close observer node
    graph.closeNode(observer);

    // 7. Notify target again
    int callCountBeforeSecondNotify = observer->getCallCount();
    target->valueChanged(true);

    // 8. Verify observer was not notified after closure
    if (observer->getCallCount() != callCountBeforeSecondNotify) {
        return false;
    }

    // 9. Return success status
    return true;
}

}  // namespace test
```

**Key Implementation Details:**

1. **Observer nodes creation**: Created two `TestObserverClosure` nodes - a target and an observer
2. **Graph instance**: Retrieved the singleton `ObserverGraph` instance using `getInstance()`
3. **Observer relationship**: Used `graph.addObserver(observer, target)` to establish that the observer watches the target
4. **Notification verification**: Called `target->valueChanged(true)` and verified the observer was notified by checking `wasChanged()` and `getCallCount()`
5. **Reset state**: Reset the observer's changed flag with `valueChanged(false)`
6. **Close node**: Used `graph.closeNode(observer)` to close the observer node, which should remove it from all relationships
7. **Notify again**: Triggered another notification on the target
8. **Verify no notification**: Confirmed the observer was NOT notified after closure by checking that the call count didn't increase
9. **Return success**: Returns `true` if all verifications pass, `false` otherwise

The implementation follows the reaction library's observer pattern where `closeNode()` removes the node from the graph and cleans up all its relationships, preventing it from receiving further notifications.

