/**
 * Function: Test filter trigger with conditional recomputation
 *
 * @param initialValue Initial sensor value
 * @param firstUpdate First update (expected to be within threshold)
 * @param secondUpdate Second update (expected to exceed threshold)
 * @param diffThreshold Minimum delta to trigger recomputation
 * @param levelThreshold Threshold to categorize HIGH vs NORMAL
 * @return std::tuple<std::string, int, int>
 *         {final status string, recompute count after first update, recompute count after second update}
 */
std::tuple<std::string, int, int> test_filter_trigger(double initialValue,
                                                      double firstUpdate,
                                                      double secondUpdate,
                                                      double diffThreshold,
                                                      double levelThreshold) {
    // 1. Create reactive variable
    auto sensor = reaction::var(initialValue);

    // 2. Create variables to track recomputation count and last processed value
    int recomputeCount = 0;
    double lastProcessedValue = initialValue;

    // 3. Create filter-triggered calculation
    auto statusCalc = reaction::calc<reaction::FilterTrig>(
        [&recomputeCount, &lastProcessedValue, levelThreshold](double value) {
            recomputeCount++;
            lastProcessedValue = value;
            return value > levelThreshold ? "HIGH" : "NORMAL";
        },
        sensor);

    // 4. Apply filter - only recompute if the difference exceeds threshold
    statusCalc.filter([&sensor, &lastProcessedValue, diffThreshold]() {
        return std::abs(sensor() - lastProcessedValue) >= diffThreshold;
    });

    // 5. Update sensor with first value
    sensor.value(firstUpdate);

    // 6. Record recompute count after first update
    int countAfterFirst = recomputeCount;

    // 7. Update sensor with second value
    sensor.value(secondUpdate);

    // 8. Record recompute count after second update
    int countAfterSecond = recomputeCount;

    // 9. Get final status
    std::string finalStatus = statusCalc.get();

    // 10. Return final status and counts
    return std::make_tuple(finalStatus, countAfterFirst, countAfterSecond);
}

}  // namespace test
```

This implementation:

1. **Creates a reactive variable** (`sensor`) initialized with `initialValue` using `reaction::var()`
2. **Tracks recomputation** using a counter (`recomputeCount`) that increments each time the calculation runs, and stores the `lastProcessedValue`
3. **Creates a filter-triggered calculation** using `reaction::calc<reaction::FilterTrig>()` that computes a status string ("HIGH" or "NORMAL") based on whether the value exceeds `levelThreshold`
4. **Applies a filter** that only triggers recomputation when the absolute difference between the current sensor value and the last processed value exceeds `diffThreshold`
5. **Updates the sensor** with `firstUpdate`
6. **Records the recompute count** after the first update
7. **Updates the sensor** with `secondUpdate`
8. **Records the recompute count** after the second update
9. **Gets the final status** from the calculation
10. **Returns** a tuple containing the final status string and both recompute counts

The key insight is that with `FilterTrig`, the calculation only re-executes when the filter condition returns `true`, allowing for conditional recomputation based on custom logic.

