    observer->addOneObserver(sensor1);

    // Step 5: Save node state for rollback
    auto rollbackFunction = graph.saveNodeStateForRollback(observer);

    // Step 6: Replace dependencies transactionally (observer now observes sensor2)
    observer->updateObservers(sensor2);

    // Step 7: Trigger notification on second sensor
    sensor2->notify(true);

    // Step 8: Record notification count after second binding
    int notificationsAfterSecondBinding = observer->notificationCount();

    // Step 9: Execute rollback (restore observer to observe sensor1)
    rollbackFunction();

    // Step 10: Trigger notification on first sensor
    sensor1->notify(true);

    // Step 11: Record notification count after rollback
    int notificationsAfterRollback = observer->notificationCount();

