Based on my exploration of the codebase, I now understand the reaction library and can implement the `test_observer_collection` function. Let me create the complete implementation:

```cpp
#pragma once

#include <reaction/reaction.h>
#include <string>

namespace test {

class NamedObserverNode : public reaction::ObserverNode {
public:
    explicit NamedObserverNode(std::string name) : m_name(std::move(name)) {}

    const std::string& name() const { return m_name; }

private:
    std::string m_name;
};

struct ObserverCollectionSummary {
    std::size_t totalObservers;
    bool containsDirectObserver;
    bool containsTransitiveObserver;
};

ObserverCollectionSummary test_observer_collection() {
    // 1. Create NamedObserverNode instances
    auto sourceNode = std::make_shared<NamedObserverNode>("sourceNode");
    auto directObserver = std::make_shared<NamedObserverNode>("directObserver");
    auto transitiveObserver = std::make_shared<NamedObserverNode>("transitiveObserver");

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(sourceNode);
    graph.addNode(directObserver);
    graph.addNode(transitiveObserver);

    // 4. Set up direct observer relationship
    // directObserver observes sourceNode
    graph.addObserver(directObserver, sourceNode);

    // 5. Set up transitive observer relationship
    // transitiveObserver observes directObserver (which observes sourceNode)
    graph.addObserver(transitiveObserver, directObserver);

    // 6. Create NodeSet to store collected observers
    reaction::NodeSet collectedObservers;

    // 7. Collect observers
    graph.collectObservers(sourceNode, collectedObservers, 1);

    // 8. Check if direct observer is in collected set
    bool hasDirectObserver = false;
    for (const auto& weakNode : collectedObservers) {
        if (auto node = weakNode.lock()) {
            auto* namedNode = dynamic_cast<NamedObserverNode*>(node.get());
            if (namedNode && namedNode->name() == "directObserver") {
                hasDirectObserver = true;
                break;
            }
        }
    }

    // 9. Check if transitive observer is in collected set
    bool hasTransitiveObserver = false;
    for (const auto& weakNode : collectedObservers) {
        if (auto node = weakNode.lock()) {
            auto* namedNode = dynamic_cast<NamedObserverNode*>(node.get());
            if (namedNode && namedNode->name() == "transitiveObserver") {
                hasTransitiveObserver = true;
                break;
            }
        }
    }

    // 10. Return collection summary
    return ObserverCollectionSummary{
        collectedObservers.size(),
        hasDirectObserver,
        hasTransitiveObserver
    };
}

}  // namespace test
```

This implementation:

1. **Creates NamedObserverNode instances** - Three nodes: sourceNode, directObserver, and transitiveObserver
2. **Gets observer graph instance** - Uses the singleton `ObserverGraph::getInstance()`
3. **Registers nodes** - Adds all three nodes to the graph using `addNode()`
4. **Sets up direct observer relationship** - Makes directObserver observe sourceNode using `addObserver()`
5. **Sets up transitive observer relationship** - Makes transitiveObserver observe directObserver (creating a chain)
6. **Creates NodeSet to store collected observers** - Declares a `reaction::NodeSet` container
7. **Collects observers** - Calls `collectObservers()` which recursively gathers all observers
8. **Checks if direct observer is in collected set** - Iterates through the set, locking weak pointers and checking names
9. **Checks if transitive observer is in collected set** - Same approach as step 8
10. **Returns collection summary** - Returns a struct with the total count and boolean flags

The `collectObservers` function recursively collects all observers of a node, so both the direct observer (directObserver) and the transitive observer (transitiveObserver) should be found in the collected set.

