/**
 * Function: Detect multi-thread registration enabling thread safety
 *
 * Tests the thread manager's ability to detect multi-threading scenarios
 * and automatically enable thread safety when multiple threads are registered.
 *
 * Steps:
 * 1. Get thread manager instance
 * 2. Reset thread manager state (for testing)
 * 3. Register current thread
 * 4. Get thread count and safety status before worker thread
 * 5. Create and start worker thread that registers itself
 * 6. Wait for worker thread to complete
 * 7. Get thread count and safety status after worker thread
 * 8. Return thread safety status containing before/after snapshots
 *
 * @return ThreadSafetyStatus Snapshots of thread manager state before and after multi-threading
 */
ThreadSafetyStatus test_thread_manager_multithread() {
    using namespace reaction;

    // 1. Get thread manager instance
    auto &tm = ThreadManager::getInstance();

    // 2. Reset thread manager state
    tm.resetForTesting();

    // 3. Register current thread
    tm.registerThread();

    // 4. Get thread count and safety status before
    const std::size_t countBefore = tm.getThreadCount();
    const bool safetyBefore = tm.isThreadSafetyEnabled();

    // 5. Create and start worker thread
    std::thread worker([]() {
        ThreadManager::getInstance().registerThread();
    });

    // 6. Wait for worker thread
    worker.join();

    // 7. Get thread count and safety status after
    const std::size_t countAfter = tm.getThreadCount();
    const bool safetyAfter = tm.isThreadSafetyEnabled();

    // 8. Return thread safety status
    return ThreadSafetyStatus{
        .safetyBefore = safetyBefore,
        .safetyAfter = safetyAfter,
        .threadCountBefore = countBefore,
        .threadCountAfter = countAfter,
    };
}

}  // namespace test
