#pragma once

#include <reaction/reaction.h>

namespace test {

struct BatchExecuteResult {
    int recomputeCountBeforeBatch;
    int recomputeCountAfterBatch;
    int finalValue;
};

BatchExecuteResult test_batch_execute_update(int baseValue, int deltaA, int deltaB) {
    using namespace reaction;

    // 1. Create reactive variable
    auto value = var(baseValue).setName("value");

    // 2. Create variable to track recomputation count
    int recomputeCount = 0;

    // 3. Create calculation
    auto calculation = calc([&]() {
        recomputeCount++;
        return value() * 2;
    }).setName("calculation");

    // Force initial evaluation
    calculation.get();

    // 4. Record recompute count before batch
    recomputeCount = 0;  // Reset counter after initial evaluation

    // First update without batch (to demonstrate difference)
    value.value(baseValue + deltaA);
    int recomputeCountBeforeBatch = recomputeCount;

    // Reset for batch test
    recomputeCount = 0;

    // 5. Execute batch updates
    batchExecute([&]() {
        value.value(baseValue + deltaA);
        value.value(baseValue + deltaA + deltaB);
    });

    // 6. Record recompute count after batch
    int recomputeCountAfterBatch = recomputeCount;

    // 7. Get final value
    int finalValue = calculation.get();

    // 8. Return batch execution result
    return BatchExecuteResult{
        recomputeCountBeforeBatch,
        recomputeCountAfterBatch,
        finalValue
    };
}

}  // namespace test
```

This implementation demonstrates the key feature of batch execution in the reaction library:

**Key Features:**
1. **Reactive Variable**: Creates a reactive variable initialized with `baseValue`
2. **Recomputation Tracking**: Uses a counter that increments each time the calculation is re-evaluated
3. **Calculation**: Creates a computed value that doubles the reactive variable's value
4. **Before Batch**: Shows that without batching, each variable change triggers a recomputation
5. **Batch Updates**: Using `batchExecute()`, multiple updates to the same variable only trigger **one** recomputation (this is the optimization)
6. **Final Value**: Returns the computed value after all updates: `(baseValue + deltaA + deltaB) * 2`

**How Batch Execution Works:**
- Without batching: Each `value.value()` call immediately triggers dependent calculations
- With batching: All updates are collected and dependencies are recomputed only once after all updates complete
- This prevents redundant computations in complex dependency graphs

The function returns a `BatchExecuteResult` showing:
- `recomputeCountBeforeBatch`: Number of recomputations for non-batched updates (typically 1 per update)
- `recomputeCountAfterBatch`: Number of recomputations for batched updates (typically 1 total)
- `finalValue`: The final computed value `(baseValue + deltaA + deltaB) * 2`

