   423→     * @param source The observing node.
   424→     * @param target The node being observed.
   425→     * @return true if a cycle would be created, false otherwise.
   426→     */
   427→    [[nodiscard]] bool hasCycle(const NodePtr &source, const NodePtr &target) {
   428→        // Check if nodes exist in the graph first to avoid at() exceptions
   429→        if (!m_dependentList.contains(source) || !m_observerList.contains(target)) {
   430→            return false; // Nodes don't exist, no cycle possible
   431→        }
   432→
   433→        // Try to get cached result first
   434→        const bool *cachedResult = m_cycleCache.getCachedCycleResult(source, target);
   435→        if (cachedResult) {
   436→            return *cachedResult;
   437→        }
   438→
   439→        // Cache miss - perform DFS and cache the result
   440→        m_dependentList.at(source).insert(target);
   441→        {
   442→            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
   443→            target->m_observers.insert(source);
   444→        }
   445→
   446→        NodeSet visited;
   447→        NodeSet recursionStack;
   448→        bool hasCycleResult = dfs(source, visited, recursionStack);
   449→
   450→        m_dependentList.at(source).erase(target);
   451→        {
   452→            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
   453→            target->m_observers.erase(source);
   454→        }
   455→
   456→        // Cache the result for future use
   457→        m_cycleCache.cacheCycleResult(source, target, hasCycleResult);
   458→
   459→        return hasCycleResult;
   460→    }
   461→
   462→    /**
   463→     * @brief DFS traversal for cycle detection.
   464→     * @param node Current node in DFS.
   465→     * @param visited Set of visited nodes.
   466→     * @param recursionStack Stack of nodes in current DFS path.
   467→     * @return true if cycle detected, false otherwise.
   468→     */
   469→    [[nodiscard]] bool dfs(const NodePtr &node, NodeSet &visited, NodeSet &recursionStack) {
   470→        if (recursionStack.contains(node)) return true;
   471→        if (visited.contains(node)) return false;
   472→
   473→        visited.insert(node);
   474→        recursionStack.insert(node);
   475→
   476→        // Check if node exists in dependent list to avoid at() exceptions
   477→        if (m_dependentList.contains(node)) {
   478→            for (auto neighbor : m_dependentList.at(node)) {
   479→                if (auto locked_neighbor = neighbor.lock()) {
   480→                    if (dfs(locked_neighbor, visited, recursionStack))
   481→                        return true;
   482→                }
   483→            }
   484→        }
   485→
   486→        recursionStack.erase(node);
   487→        return false;
   488→    }
   489→
   490→    /**
   491→     * @brief Internal reset operation without locking.
   492→     * Should only be called when graph mutex is already held.
   493→     * @param node The node to reset.
   494→     */
   495→    void resetNodeInternal(const NodePtr &node) {
   496→        if (!node) return;
   497→
   498→        // Clean up dependent relationships - this node observes others
   499→        if (m_dependentList.contains(node)) {
   500→            for (auto dep : m_dependentList[node]) {
   501→                if (auto locked_dep = dep.lock()) {
   502→                    if (m_observerList.contains(locked_dep)) {
   503→                        // Take the node's observer mutex before modifying its observer set
   504→                        ConditionalUniqueLock<ConditionalSharedMutex> observerLock(locked_dep->m_observersMutex);
   505→                        m_observerList.at(locked_dep).get().erase(node);
   506→                    }
   507→                }
   508→            }
   509→            m_dependentList.at(node).clear();
   510→        }
   511→    }
   512→
   513→    /**
   514→     * @brief Internal add observer operation without locking.
   515→     * Should only be called when graph mutex is already held.
   516→     * @param source The observing node.
   517→     * @param target The node being observed.
   518→     */
   519→    void addObserverInternal(const NodePtr &source, const NodePtr &target) {
   520→        if (source == target) {
   521→            REACTION_THROW_SELF_OBSERVATION(getNameInternal(source));
   522→        }
   523→
   524→        // Ensure both nodes exist in the graph
   525→        if (!m_dependentList.contains(source)) {
   526→            addNodeInternal(source);
   527→        }
   528→        if (!m_observerList.contains(target)) {
   529→            addNodeInternal(target);
   530→        }
   531→
   532→        if (hasCycle(source, target)) {
   533→            REACTION_THROW_DEPENDENCY_CYCLE(getNameInternal(source), getNameInternal(target));
   534→        }
   535→
   536→        m_dependentList.at(source).insert(target);
   537→        {
   538→            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
   539→            target->m_observers.insert(source);
   540→        }
   541→    }
   542→
   543→    std::unordered_map<NodePtr, NodeSetRef> m_observerList;                 ///< Map from node to its observers (refs).
   544→    std::unordered_map<NodePtr, NodeSet> m_dependentList;                   ///< Map from node to its dependencies.
   545→    std::unordered_map<NodePtr, std::string> m_nameList;                    ///< Human-readable node names.
   546→    std::unordered_map<NodePtr, std::set<const void *>> m_activeBatchNodes; ///< Map from node to active batch IDs.
   547→    std::set<const void *> m_activeBatchIds;                                ///< Set of all active batch IDs.
   548→
   549→    // Cache subsystems
   550→    mutable GraphTraversalCache m_graphCache; ///< Cache for graph traversal results.
   551→    mutable CycleDetectionCache m_cycleCache; ///< Cache for cycle detection results.
   552→    mutable NodeMetricsCache m_metricsCache;  ///< Cache for node metrics and existence checks.
   553→};
   554→
   555→/**
   556→ * @brief Implementation of ObserverGraph::addNode.
   557→ *
   558→ * Initializes internal data structures for the given node.
   559→ * @param node Node to add.
   560→ */
   561→inline void ObserverGraph::addNode(const NodePtr &node) noexcept {
   562→    REACTION_REGISTER_THREAD();
   563→    ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
   564→    m_observerList.insert({node, std::ref(node->m_observers)});
   565→    m_dependentList[node] = NodeSet{};
   566→}
   567→
   568→/**
   569→ * @brief Implementation of ObserverGraph::addNodeInternal.
   570→ *
   571→ * Initializes internal data structures for the given node without locking.
   572→ * @param node Node to add.
   573→ */
   574→inline void ObserverGraph::addNodeInternal(const NodePtr &node) noexcept {
   575→    m_observerList.insert({node, std::ref(node->m_observers)});
   576→    m_dependentList[node] = NodeSet{};
   577→}
   578→
   579→/**
   580→ * @brief Implementation of ObserverGraph::collectObservers.
   581→ * @param node origin node to find observers.
   582→ * @param observers container for output observers.
   583→ * @param depth current dependent depth.
   584→ */
   585→inline void ObserverGraph::collectObservers(const NodePtr &node, NodeSet &observers, uint16_t depth = 1) noexcept {
   586→    if (!node) return;
   587→
   588→    NodeSet currentObservers;
   589→    {
   590→        ConditionalSharedLock<ConditionalSharedMutex> lock(m_graphMutex);
   591→        // Try to get cached immediate observers first
   592→        const NodeSet *cachedObservers = m_graphCache.getCachedImmediateObservers(node);
   593→
   594→        if (cachedObservers) {
   595→            // Use cached data - still need to update depth and collect recursively
   596→            currentObservers = *cachedObservers;
   597→            for (auto &ob : currentObservers) {
   598→                if (auto wp = ob.lock()) [[likely]] {
   599→                    wp->updateDepth(depth);
   600→                    observers.insert(ob);
   601→                }
   602→            }
   603→        } else {
   604→            // Cache miss - collect from graph and cache the result
   605→            if (m_observerList.contains(node)) {
   606→                for (auto &ob : m_observerList.at(node).get()) {
   607→                    if (auto wp = ob.lock()) [[likely]] {
   608→                        wp->updateDepth(depth);
   609→                        observers.insert(ob);
   610→                        currentObservers.insert(ob);
   611→                    }
   612→                }
   613→                // Cache the immediate observers for future use
   614→                m_graphCache.cacheImmediateObservers(node, currentObservers);
   615→            }
   616→        }
   617→    }
   618→
   619→    // Process collected observers recursively without holding lock
   620→    for (auto &ob : currentObservers) {
   621→        if (auto wp = ob.lock()) [[likely]] {
   622→            collectObservers(wp, observers, depth + 1);
   623→        }
   624→    }
   625→}
   626→
   627→} // namespace reaction
