#pragma once

#include "reaction/core/observer_node.h"
#include "reaction/graph/observer_graph.h"
#include "reaction/core/types.h"
#include <memory>

namespace test {

class CacheProbeNode : public reaction::ObserverNode {
public:
    void valueChanged(bool changed = true) override {
        // Custom implementation for testing - just call base notify
        this->notify(changed);
    }
};

struct CacheStatsSnapshot {
    size_t graphEntriesBeforeCleanup;
    size_t graphEntriesAfterCleanup;
    double graphHitRatioAfterCleanup;
};

CacheStatsSnapshot test_observer_cache_stats() {
    // 1. Create CacheProbeNode instances
    auto node1 = std::make_shared<CacheProbeNode>();
    auto node2 = std::make_shared<CacheProbeNode>();
    auto node3 = std::make_shared<CacheProbeNode>();
    auto node4 = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(node1);
    graph.addNode(node2);
    graph.addNode(node3);
    graph.addNode(node4);

    // 4. Set up direct observer relationship
    // node1 observes node2
    graph.addObserver(node1, node2);

    // 5. Set up transitive observer relationship
    // node3 observes node1 (which observes node2, creating a transitive relationship)
    graph.addObserver(node3, node1);
    // node4 observes node2 (another direct observer)
    graph.addObserver(node4, node2);

    // 6. Create NodeSet to store collected observers
    reaction::NodeSet collectedObservers;

    // 7. Populate cache data by calling collectObservers multiple times
    // This will cache the immediate observers for each node
    graph.collectObservers(node2, collectedObservers, 1);
    collectedObservers.clear();
    graph.collectObservers(node1, collectedObservers, 1);
    collectedObservers.clear();
    graph.collectObservers(node2, collectedObservers, 1); // Second call should hit cache

    // 8. Get cache statistics before cleanup
    auto statsBeforeCleanup = graph.getCacheStats();
    size_t graphEntriesBeforeCleanup = statsBeforeCleanup.graphStats.totalEntries;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfterCleanup = graph.getCacheStats();
    size_t graphEntriesAfterCleanup = statsAfterCleanup.graphStats.totalEntries;
    double graphHitRatioAfterCleanup = statsAfterCleanup.graphStats.hitRatio;

    // 11. Close all nodes
    graph.closeNode(node1);
    graph.closeNode(node2);
    graph.closeNode(node3);
    graph.closeNode(node4);

    // 12. Return cache stats snapshot
    return CacheStatsSnapshot{
        graphEntriesBeforeCleanup,
        graphEntriesAfterCleanup,
        graphHitRatioAfterCleanup
    };
}

}  // namespace test

