   788→
   789→    // Create shared reactive objects
   790→    std::vector<reaction::Var<int>> sharedVars(N);
   791→    std::vector<reaction::Calc<int>> sharedCalcs(N);
   792→    std::vector<reaction::Action<>> sharedActions(N);
   793→
   794→    // Initialize reactive objects
   795→    for (int i = 0; i < N; ++i) {
   796→        sharedVars[i] = reaction::var(i);
   797→        sharedCalcs[i] = reaction::calc([]() { return 1; });
