   799→    }
   800→
   801→    std::atomic<int> operationsCompleted{0};
   802→    std::atomic<bool> raceDetected{false};
   803→    std::vector<std::thread> threads1, threads2;
   804→
   805→    // Thread function 1: Reset calculations to depend on random variables
   806→    auto calcResetTask = [&]() {
   807→        try {
   808→            // Thread-local random number generator
   809→            std::mt19937 gen(std::random_device{}());
   810→            std::uniform_int_distribution<> dist(0, N - 1);
   811→
   812→            for (int i = 0; i < 5; ++i) { // Perform 5 operations per thread
   813→                auto rd1 = dist(gen);
   814→                auto rd2 = dist(gen);
   815→                auto rd3 = dist(gen);
   816→
   817→                // Reset calculation to depend on two random variables
   818→                sharedCalcs[rd1].reset([&, rd2, rd3]() {
   819→                    return sharedVars[rd2]() + sharedVars[rd3]();
   820→                });
   821→
   822→                operationsCompleted++;
   823→            }
   824→        } catch (const std::exception &e) {
   825→            std::cout << "Calc reset task caught exception: " << e.what() << std::endl;
   826→            raceDetected = true;
   827→        } catch (...) {
   828→            std::cout << "Calc reset task caught unknown exception" << std::endl;
   829→            raceDetected = true;
   830→        }
   831→    };
   832→
   833→    // Thread function 2: Reset actions to print calculation results
   834→    auto actionResetTask = [&]() {
   835→        try {
   836→            // Thread-local random number generator
   837→            std::mt19937 gen(std::random_device{}());
   838→            std::uniform_int_distribution<> dist(0, N - 1);
   839→
   840→            for (int i = 0; i < 5; ++i) { // Perform 5 operations per thread
   841→                auto rd1 = dist(gen);
   842→                auto rd2 = dist(gen);
