 * See the LICENSE file in the project root for full details.
 */

#pragma once

#include "reaction/memory/sbo_resource.h"
#include "reaction/memory/stack_monitor.h"
#include <memory>

namespace test {

struct ResourceSBOState {
    bool smallTypeUsesSBO;
    bool largeTypeUsesSBO;
};

inline ResourceSBOState test_resource_sbo() {
    using namespace reaction::memory;

    // Initialize stack monitor for SBO tracking
    StackMonitor::initialize();

    // 1. Define type aliases for small and large resource types
    // Small type: fits within ALWAYS_SBO_SIZE (16 bytes)
    using SmallResourceType = int;  // 4 bytes

    // Large type: exceeds MAX_SBO_SIZE (64 bytes), forcing heap allocation
    struct LargeResourceType {
        char data[128];  // 128 bytes - forces heap allocation
    };

    // 2. Create small resource instance
    auto smallResource = std::make_shared<SBOResource<SmallResourceType>>(42);

    // 3. Create large resource instance
    auto largeResource = std::make_shared<SBOResource<LargeResourceType>>(LargeResourceType{});

    // 4. Query whether small resource uses SBO
    bool smallTypeUsesSBO = smallResource->isUsingSBO();

    // 5. Query whether large resource uses SBO
    bool largeTypeUsesSBO = largeResource->isUsingSBO();

    // 6. Return resource SBO state
    return ResourceSBOState{
        .smallTypeUsesSBO = smallTypeUsesSBO,
        .largeTypeUsesSBO = largeTypeUsesSBO
    };
}

}  // namespace test
```

## Explanation:

This implementation uses the **reaction** library's `SBOResource` class for Small Buffer Optimization (SBO). Here's what the function does:

1. **Type Aliases**: Defines two types:
   - `SmallResourceType` (int, 4 bytes): Small enough to use SBO (≤ 16 bytes threshold)
   - `LargeResourceType` (128 bytes): Too large for SBO, will use heap allocation

2. **Resource Creation**: Creates instances of both types using `SBOResource` template

3. **SBO Queries**: Uses the `isUsingSBO()` method to check whether each resource is using stack-based (SBO) or heap-based storage

4. **Return State**: Returns a `ResourceSBOState` struct with the SBO status of both resources

**Expected behavior**:
- `smallTypeUsesSBO` will be `true` (uses stack storage)
- `largeTypeUsesSBO` will be `false` (uses heap storage)

The implementation follows the pattern shown in the test file (`test_sbo.cpp`) and leverages the library's automatic SBO optimization based on type size.

