namespace test {

struct LastHandleSnapshot {
    int initialValue;
    int afterUpdate;
    int afterSourceClose;
};

LastHandleSnapshot test_last_handle_restore(int initialValue, int updatedValue) {
    // 1. Create a reactive variable
    auto source = reaction::var(initialValue);

    // 2. Create a calculation with LastHandle policy
    // LastHandle policy captures the last known value when the source is invalidated/closed
    auto calc = reaction::calc<reaction::ChangeTrig, reaction::LastHandle>(
        [](int value) { return value; }, 
        source
    );

    // 3. Get the initial result
    int initial = calc.get();

    // 4. Update the source variable
    source.value(updatedValue);

    // 5. Get the updated result
    int afterUpdate = calc.get();

    // 6. Close the source node
    source.close();

    // 7. Get the result after source close
    // Due to LastHandle policy, this should still return the last value (updatedValue)
    // because LastHandle replaces the expression with a constant returning the last value
    int afterClose = calc.get();

    // 8. Return last handle snapshot
    return LastHandleSnapshot{
        initial,
        afterUpdate,
        afterClose
    };
}

}  // namespace test
```

This implementation:

