#pragma once

#include <array>
#include <memory>
#include "reaction/memory/sbo_resource.h"

namespace test {

struct SmallPayload {
    int value;
    bool operator!=(const SmallPayload& other) const = default;
};

struct LargePayload {
    std::array<int, 64> data{};
    bool operator!=(const LargePayload& other) const = default;
};

struct SboStorageStatus {
    bool updateReportedChange;
    bool smallUsingSBO;
    std::size_t smallStackUsage;
    bool largeInitialized;
    bool largeUsingSBO;
};

SboStorageStatus test_sbo_storage_info(int initialSmall,
                                       int updatedSmall,
                                       int largeSeed) {
    // 1. Create a lambda function to make large payload
    auto makeLargePayload = [](int seed) {
        LargePayload payload;
        for (size_t i = 0; i < payload.data.size(); ++i) {
            payload.data[i] = seed + static_cast<int>(i);
        }
        return payload;
    };

    // 2. Create small SBOResource
    auto smallResource = std::make_shared<reaction::memory::SBOResource<SmallPayload>>(
        SmallPayload{initialSmall}
    );

    // 3. Create large SBOResource
    auto largeResource = std::make_shared<reaction::memory::SBOResource<LargePayload>>(
        makeLargePayload(largeSeed)
    );

    // 4. Update small resource value
    bool updateReportedChange = smallResource->updateValue(SmallPayload{updatedSmall});

    // 5. Get storage information for small resource
    auto smallInfo = smallResource->getStorageInfo();

    // 6. Get storage information for large resource
    auto largeInfo = largeResource->getStorageInfo();

    // 7. Return SBO storage status
    return SboStorageStatus{
        .updateReportedChange = updateReportedChange,
        .smallUsingSBO = smallInfo.using_sbo,
        .smallStackUsage = smallInfo.stack_usage,
        .largeInitialized = largeInfo.initialized,
        .largeUsingSBO = largeInfo.using_sbo
    };
}

}  // namespace test
```

This implementation:

1. **Creates a lambda function** (`makeLargePayload`) that takes a seed integer and generates a `LargePayload` with the data array populated based on the seed value.

2. **Creates a small SBOResource** using `SmallPayload` with the `initialSmall` value. Since `SmallPayload` is small (just one int), it should use stack-based SBO storage.

3. **Creates a large SBOResource** using `LargePayload` generated from the lambda. Since `LargePayload` contains an array of 64 integers (256 bytes), it will be forced to use heap allocation.

4. **Updates the small resource value** to `updatedSmall` and captures whether the update reported a change (returns `true` if the value changed, `false` if it was the same).

5. **Gets storage information** for the small resource using the `getStorageInfo()` method from the SBOResource API.

6. **Gets storage information** for the large resource similarly.

7. **Returns an SboStorageStatus struct** with all the collected information about SBO usage, initialization status, and stack usage.

The implementation uses the third-party `reaction::memory::SBOResource` class which provides Small Buffer Optimization (SBO) - automatically choosing between stack and heap allocation based on the size of the type being stored.

