   202→/**
   203→ * @brief Core test: detect data races (tearing)
   204→ *
   205→ * This test writes compound structures to check for torn reads/writes.
   206→ * - With mutex disabled → tearing should be detected → FAIL
   207→ * - With mutex enabled  → no tearing → PASS
   208→ */
   209→TEST(ThreadSafetyTest, ThreadSafetyVerification) {
   210→    auto &manager = reaction::ThreadManager::getInstance();
   211→    manager.resetForTesting();
   212→
   213→    struct TestData {
   214→        int a;
   215→        int b;
   216→        TestData(int x = 0, int y = 0) : a(x), b(y) {}
   217→        bool isValid() const { return a == b; } // valid if a == b
   218→    };
   219→
   220→    auto sharedVar = reaction::var(TestData(0, 0));
   221→    std::atomic<bool> raceDetected{false};
   222→    std::atomic<int> readCount{0};
   223→    std::atomic<int> writeCount{0};
   224→    std::atomic<int> tearingCount{0};
   225→
   226→    // Writer
   227→    auto writer = [&]() {
   228→        for (int i = 1; i <= 5000; ++i) {
   229→            try {
   230→                TestData data(i, i);
   231→                sharedVar.value(data);
   232→                writeCount++;
   233→                std::this_thread::sleep_for(std::chrono::nanoseconds(500));
   234→            } catch (const std::exception &e) {
   235→                raceDetected = true;
   236→            }
   237→        }
   238→    };
   239→
   240→    // Reader
   241→    auto reader = [&]() {
   242→        for (int i = 0; i < 10000; ++i) {
   243→            try {
   244→                TestData data = sharedVar.get();
   245→                readCount++;
   246→                if (!data.isValid() && !(data.a == 0 && data.b == 0)) {
   247→                    std::cout << "Data tearing detected! a=" << data.a << ", b=" << data.b << std::endl;
   248→                    tearingCount++;
   249→                    raceDetected = true;
   250→                }
   251→                std::this_thread::sleep_for(std::chrono::nanoseconds(250));
   252→            } catch (const std::exception &e) {
   253→                raceDetected = true;
   254→            }
   255→        }
   256→    };
   257→
   258→    std::thread w1(writer);
   259→    std::thread w2(writer);
   260→    std::thread r1(reader);
   261→    std::thread r2(reader);
   262→
   263→    w1.join();
   264→    w2.join();
   265→    r1.join();
   266→    r2.join();
   267→
   268→    std::cout << "=== Thread Safety Verification Result ===" << std::endl;
   269→    std::cout << "Read operations: " << readCount.load() << std::endl;
   270→    std::cout << "Write operations: " << writeCount.load() << std::endl;
   271→    std::cout << "Tearing detected: " << tearingCount.load() << std::endl;
   272→
   273→    if (raceDetected.load()) {
   274→        FAIL() << "Thread safety protection failed! Tearing detected " << tearingCount.load() << " times";
   275→    }
   276→
   277→    EXPECT_EQ(readCount.load(), 20000);  // 2 readers * 10000
   278→    EXPECT_EQ(writeCount.load(), 10000); // 2 writers * 5000
   279→    EXPECT_EQ(tearingCount.load(), 0);   // no tearing expected
   280→}
