   135→
   136→    // First, make calc1 depend on calc2
   137→    calc1.reset([&]() { return calc2() + 1; });
   138→    EXPECT_EQ(calc1.get(), 3); // b(2) + 1 = 3
   139→
   140→    // Now attempt to make calc2 depend on calc1, creating a cycle
   141→    EXPECT_THROW(calc2.reset([&]() { return calc1() + 1; }), std::runtime_error);
   142→
   143→    // Verify calc2 is still in a consistent state
   144→    EXPECT_EQ(calc2.get(), 2);
   145→
   146→    // Verify calc2's dependencies are still intact
   147→    b.value(5);
   148→    EXPECT_EQ(calc2.get(), 5);
   149→}
