    17→/**
    18→ * @brief Test automatic disabling of thread safety in single-threaded mode
    19→ */
    20→TEST(ThreadSafetyTest, SingleThreadAutoDisable) {
    21→    std::cout << "=== Single-thread Auto-disable Test ===" << std::endl;
    22→
    23→    // Reset thread safety manager state (for testing purpose)
    24→    auto &manager = reaction::ThreadManager::getInstance();
    25→    manager.resetForTesting();
    26→
    27→    // Check initial state before creating variables
    28→    bool initialState = manager.isThreadSafetyEnabled();
    29→    std::cout << "Thread safety state at test start: " << (initialState ? "Enabled" : "Disabled") << std::endl;
    30→
    31→    // Create variable and perform operations
    32→    auto var = reaction::var(42);
    33→    int value1 = var.get(); // This triggers REACTION_REGISTER_THREAD
    34→    var.value(100);
    35→    int value2 = var.get();
    36→
    37→    // Check thread safety state
    38→    bool afterSingleThread = manager.isThreadSafetyEnabled();
    39→    std::cout << "Thread safety state after single-thread operations: " << (afterSingleThread ? "Enabled" : "Disabled") << std::endl;
    40→
    41→    // Verify results
    42→    EXPECT_EQ(value1, 42);
    43→    EXPECT_EQ(value2, 100);
    44→    EXPECT_FALSE(afterSingleThread) << "Thread safety should be disabled in single-thread mode";
    45→
    46→    std::cout << "✅ Single-thread auto-disable test passed" << std::endl;
    47→}
