    12→// Test reset consistency guarantees
    13→TEST(ResetConsistencyTest, ResetCycleDependencyRollback) {
    14→    auto a = reaction::var(1);
    15→    auto b = reaction::var(2);
    16→
    17→    // Create a valid calculation first
    18→    auto calc = reaction::calc([](int x, int y) { return x + y; }, a, b);
    19→    EXPECT_EQ(calc.get(), 3);
    20→
    21→    // Change values and verify calculation still works
    22→    a.value(10);
    23→    EXPECT_EQ(calc.get(), 12);
    24→
    25→    // Attempt to reset with a cycle dependency (should fail and rollback)
    26→    EXPECT_THROW(calc.reset([&]() { return a() + calc(); }), std::runtime_error);
    27→
    28→    // Verify the node is still in a consistent state
    29→    EXPECT_EQ(calc.get(), 12); // Value should be unchanged
    30→
    31→    // Verify dependencies are still intact by changing inputs
    32→    a.value(20);
    33→    EXPECT_EQ(calc.get(), 22);
    34→    b.value(5);
    35→    EXPECT_EQ(calc.get(), 25);
    36→}
