#pragma once

#include <reaction/reaction.h>
#include <string>

namespace test {

/**
 * @brief Observer node that tracks notifications for testing purposes.
 *
 * This node extends ObserverNode to count how many times it has been
 * notified. Useful for testing graph notification behavior.
 */
class ResetAwareNode : public reaction::ObserverNode {
public:
    explicit ResetAwareNode(std::string name)
        : m_name(std::move(name)), m_notificationCount(0) {
        // Register this node with the observer graph
        auto graph = &reaction::ObserverGraph::getInstance();
        graph->addNode(shared_from_this());
        graph->setName(shared_from_this(), m_name);
    }

    /**
     * @brief Override valueChanged to track notifications.
     * @param changed Whether the value has changed.
     */
    void valueChanged(bool changed = true) override {
        m_notificationCount++;
        ObserverNode::valueChanged(changed);
    }

    /**
     * @brief Get the number of times this node has been notified.
     * @return The notification count.
     */
    int notifications() const {
        return m_notificationCount;
    }

    /**
     * @brief Clear the notification count.
     */
    void clear() {
        m_notificationCount = 0;
    }

private:
    std::string m_name;
    int m_notificationCount;
};

/**
 * @brief Result structure for test_graph_reset_node function.
 */
struct ResetNodeResult {
    bool notifiedBeforeReset;
    bool notifiedAfterReset;
};

/**
 * @brief Test function for graph node reset behavior.
 *
 * This function tests that when a node is reset, it properly disconnects
 * from the observer graph and no longer receives notifications.
 *
 * @param sourceName Name of the source node that triggers notifications.
 * @param targetName Name of the target node that receives notifications.
 * @return ResetNodeResult containing notification status before and after reset.
 */
ResetNodeResult test_graph_reset_node(const std::string &sourceName,
                                      const std::string &targetName) {
    // Step 1: Create source and target ResetAwareNode instances
    auto source = std::make_shared<ResetAwareNode>(sourceName);
    auto target = std::make_shared<ResetAwareNode>(targetName);

    // Step 2: Get observer graph instance
    auto &graph = reaction::ObserverGraph::getInstance();

    // Step 3: Register nodes (already done in constructor, but be explicit)
    graph.setName(source, sourceName);
    graph.setName(target, targetName);

    // Step 4: Set up observer relationship (target observes source)
    // This means when source notifies, target gets notified
    graph.addObserver(target, source);

    // Step 5: Trigger notification on source
    source->notify();

    // Step 6: Check if target was notified before reset
    bool notifiedBeforeReset = (target->notifications() > 0);

    // Step 7: Clear target notification count
    target->clear();

    // Step 8: Reset target node (remove all its dependencies)
    graph.resetNode(target);

    // Step 9: Trigger notification on source again
    source->notify();

    // Step 10: Check if target was notified after reset
    // After reset, target should NOT receive notifications
    bool notifiedAfterReset = (target->notifications() > 0);

    // Step 11: Close nodes to clean up
    graph.closeNode(source);
    graph.closeNode(target);

    // Step 12: Return reset node result
    return ResetNodeResult{notifiedBeforeReset, notifiedAfterReset};
}

}  // namespace test

