inline StackAllocationSnapshot test_stack_monitor_capacity(std::size_t largeSize) {
    using namespace reaction::memory;

    StackAllocationSnapshot snapshot{};

    // Step 1: Disable monitoring
    StackMonitor::setMonitoringEnabled(false);

    // Step 2: Initialize stack monitor
    StackMonitor::initialize();

    // Step 3: Check allocation without monitoring
    // Without monitoring, canAllocate checks against CONDITIONAL_SBO_SIZE (32 bytes)
    snapshot.smallAllowedWithoutMonitoring = StackMonitor::canAllocate<16>();
    snapshot.largeAllowedWithoutMonitoring = StackMonitor::canAllocate<64>();
    snapshot.runtimeAllowedWithoutMonitoring = StackMonitor::canAllocate(largeSize);

    // Step 4: Enable monitoring
    StackMonitor::setMonitoringEnabled(true);

    // Step 5: Initialize stack monitor again
    StackMonitor::initialize();

    // Step 6: Check large allocation with monitoring
    // With monitoring, canAllocate checks against MAX_SBO_STACK_USAGE (64KB)
    snapshot.largeAllowedWithMonitoring = StackMonitor::canAllocate<1024>();

    // Step 7: Create StackGuard in scope block
    {
        // Allocate close to the limit to test blocking behavior
        constexpr std::size_t limitSize = SBOConfig::MAX_SBO_STACK_USAGE - 1024;
        StackMonitor::StackGuard<limitSize> guard;

        // Step 8: Check if guard succeeded
        snapshot.guardSucceeded = guard.success();

        // Step 9: Check if allocation blocked at limit
        // Try to allocate more than the remaining capacity
        snapshot.allocationBlockedAtLimit = !StackMonitor::canAllocate<2048>();

        // Step 10: Exit guard scope (destructor called automatically)
    }

    // Step 11: Check runtime allocation after release
    snapshot.runtimeAllowedAfterRelease = StackMonitor::canAllocate(largeSize);

    // Step 12: Return stack allocation snapshot
    return snapshot;
}

}  // namespace test
