    16→ */
    17→TEST(ExpressionOperatorsTest, TestComparisonOperators) {
    18→    using namespace reaction;
    19→
    20→    auto a = var(5).setName("a");
    21→    auto b = var(3).setName("b");
    22→    auto c = var(5).setName("c");
    23→
    24→    // Test equality
    25→    auto eq_expr = expr(a == c).setName("eq_expr");
