    55→
    56→    auto le_expr2 = expr(a <= c).setName("le_expr2");
    57→    EXPECT_TRUE(le_expr2.get());
    58→
    59→    // Test greater than or equal
    60→    auto ge_expr = expr(a >= b).setName("ge_expr");
