   727→                // Use atomic increment operation instead of read-modify-write
   728→                ++sharedCounter; // This uses the atomic pre-increment operator
   729→                totalOperationsPerformed++;
   730→            }
   731→            threadsCompleted++;
   732→        } catch (const std::exception &e) {
